import{_ as e,o as i,c as a,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"2020-03-03 -- Ceph Testing Meeting","description":"","frontmatter":{"title":"2020-03-03 -- Ceph Testing Meeting","date":"2020-03-03T00:00:00.000Z","updated":"2020-04-04T00:00:00.000Z","tags":["Ceph","测试","分布式存储","CRUSH 算法","高可用性"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2020/2020-03-03_-_-_Ceph_Testing_Meeting.md","filePath":"posts/2020/2020-03-03_-_-_Ceph_Testing_Meeting.md","lastUpdated":1780460162000}'),o={name:"posts/2020/2020-03-03_-_-_Ceph_Testing_Meeting.md"};function r(s,l,n,h,_,p){return i(),a("div",null,[...l[0]||(l[0]=[t('<p>会议纪要：</p><h3 id="会议概述" tabindex="-1">会议概述 <a class="header-anchor" href="#会议概述" aria-label="Permalink to &quot;会议概述&quot;">​</a></h3><p>本次会议主要讨论了Ceph分布式存储系统的测试进展及相关议题。</p><h4 id="会议要点" tabindex="-1">会议要点 <a class="header-anchor" href="#会议要点" aria-label="Permalink to &quot;会议要点&quot;">​</a></h4><ol><li><p><strong>Ceph Master分支的补丁测试</strong></p><ul><li>讨论了与Cat Food合作的Master分支补丁，特别是与Pi3兼容性的两个测试。</li><li>强调了需要进一步测试其余部分的覆盖率，并可能需要其他人员的帮助。</li></ul></li><li><p><strong>分支管理和测试</strong></p><ul><li>讨论了Octopus分支的当前状态，以及Master分支的工作内容。</li><li>确定了哪些分支仍然活跃，以及如何确定哪些分支需要回溯更改。</li></ul></li><li><p><strong>测试框架的使用</strong></p><ul><li>讨论了ToTology和SEF CI的使用，以及它们在现有集群上的应用。</li><li>询问了如何利用ToTology在现有集群上执行测试，以及是否可行。</li></ul></li><li><p><strong>调度问题</strong></p><ul><li>讨论了调度裸机桌面的问题，以及如何改进锁定机制。</li><li>提到了需要重新设计队列机制，以更好地管理资源和优先级。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h4><ul><li>需要进一步测试Master分支的补丁，确保不会破坏现有流程。</li><li>需要确定哪些分支需要回溯更改，并与Sage确认。</li><li>需要与相关人员讨论如何利用ToTology在现有集群上执行测试。</li><li>重新设计队列机制，以改进资源管理和优先级设置。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li>继续测试Master分支的补丁，并确保其兼容性。</li><li>与Sage确认哪些分支需要回溯更改。</li><li>与相关人员讨论ToTology在现有集群上的应用，并寻求解决方案。</li><li>重新设计队列机制，以改进资源管理和优先级设置。</li></ul><h4 id="其他备注" tabindex="-1">其他备注 <a class="header-anchor" href="#其他备注" aria-label="Permalink to &quot;其他备注&quot;">​</a></h4><ul><li>会议被录音，录音文件将存档。</li></ul><h3 id="修正与补充" tabindex="-1">修正与补充 <a class="header-anchor" href="#修正与补充" aria-label="Permalink to &quot;修正与补充&quot;">​</a></h3><ul><li>原总结中未提及ToTology和SEF CI的具体应用场景和功能。</li><li>原总结中未提及与Python 3兼容性的问题。</li><li>原总结中未提及与Sage的沟通确认。</li><li>原总结中未提及队列机制的重新设计细节。</li></ul>',13)])])}const g=e(o,[["render",r]]);export{u as __pageData,g as default};
